# ============================================================
# 029_PCA_Quantile_Classification_CORREGIDO.R
#
# Objective 4
# PCA + quantiles operational classification
#
# PURPOSE
# Apply the previously defined P25-P75 rule to the same
# multivariate Behavioural_Index generated by the corrected
# Swaminathan-like script.
#
# METHOD PRESERVED FROM THE PREVIOUS OBJECTIVE 4 WORKFLOW
# - Use the same Behavioural_Index already constructed from PC1-PC4.
# - Restrict the classification to the 89 Stress fish.
# - Calculate P25 and P75 within the Stress population only.
# - Behavioural_Index <= P25  -> Susceptible
# - Behavioural_Index >= P75  -> Resilient
# - P25 < Behavioural_Index < P75 -> Intermediate
#
# CORRECTED ANALYTICAL FOUNDATION
# - Traceability = Author + ID.
# - Stress population = the definitive 89 fish from Objective 3.
# - Behavioural coordinates inherited unchanged:
#     distance_rz
#     crossing_rz
#     top_entry_rz
#     top_time_rz
# - No behavioural variable is renormalised.
# - No PCA is refitted.
# - No new behavioural index is constructed in this script.
# ============================================================

script_version <- paste(
  "029_PCA_Quantile_Classification_CORREGIDO",
  "| 2026-08-09",
  "| corrected Objective 1-3 dependencies"
)

cat("\nRunning: ", script_version, "\n", sep = "")

# ------------------------------------------------------------
# 1. Project directory and packages
# ------------------------------------------------------------

project_root <- "C:/Users/USER/Documents/LAPCOM_UCS_Resilience"

if (!dir.exists(project_root)) {
  stop("Project directory not found:\n", project_root)
}

setwd(project_root)

required_packages <- c(
  "dplyr",
  "tibble",
  "ggplot2",
  "openxlsx"
)

missing_packages <- required_packages[
  !vapply(
    required_packages,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following packages before running this script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

suppressPackageStartupMessages({
  library(dplyr)
  library(tibble)
  library(ggplot2)
  library(openxlsx)
})

# ------------------------------------------------------------
# 2. Fixed analytical configuration
# ------------------------------------------------------------

expected_stress_n <- 89L

robust_variables <- c(
  "distance_rz",
  "crossing_rz",
  "top_entry_rz",
  "top_time_rz"
)

pc_variables <- paste0(
  "PC",
  1:4
)

required_classes <- c(
  "Susceptible",
  "Intermediate",
  "Resilient"
)

numeric_tolerance <- 1e-10

# ------------------------------------------------------------
# 3. Input and output paths
# ------------------------------------------------------------

objects_dir <- file.path(
  project_root,
  "03_Results",
  "Objects"
)

tables_dir <- file.path(
  project_root,
  "03_Results",
  "Tables"
)

figures_dir <- file.path(
  project_root,
  "03_Results",
  "Figures"
)

processed_dir <- file.path(
  project_root,
  "01_Data",
  "Processed"
)

for (directory_i in c(
  objects_dir,
  tables_dir,
  figures_dir
)) {
  if (!dir.exists(directory_i)) {
    dir.create(
      directory_i,
      recursive = TRUE
    )
  }
}

swaminathan_file <- file.path(
  objects_dir,
  "objective4_swaminathan_classification.rds"
)

stress_objective3_file <- file.path(
  processed_dir,
  "objective3_stress_robust_z_control_reference.rds"
)

required_input_files <- c(
  swaminathan_file,
  stress_objective3_file
)

missing_input_files <- required_input_files[
  !file.exists(required_input_files)
]

if (length(missing_input_files) > 0L) {
  stop(
    "The following corrected input files were not found:\n",
    paste(missing_input_files, collapse = "\n")
  )
}

classification_output <- file.path(
  objects_dir,
  "objective4_pca_quantile_classification.rds"
)

summary_output <- file.path(
  objects_dir,
  "objective4_pca_quantile_summary.rds"
)

thresholds_output <- file.path(
  objects_dir,
  "objective4_pca_quantile_thresholds.rds"
)

method_size_output <- file.path(
  objects_dir,
  "objective4_preliminary_method_size_table.rds"
)

xlsx_output <- file.path(
  tables_dir,
  "Objective4_PCA_Quantile_Classification.xlsx"
)

pdf_output <- file.path(
  figures_dir,
  "Objective4_PCA_Quantile_Classification.pdf"
)

tiff_output <- file.path(
  figures_dir,
  "Objective4_PCA_Quantile_Classification.tiff"
)

session_info_output <- file.path(
  objects_dir,
  "objective4_pca_quantile_sessionInfo.txt"
)

# ------------------------------------------------------------
# 4. Load corrected Swaminathan object and Objective 3 Stress data
# ------------------------------------------------------------

classification_swaminathan <- readRDS(
  swaminathan_file
)

stress_objective3 <- readRDS(
  stress_objective3_file
)

if (!is.data.frame(classification_swaminathan)) {
  stop(
    basename(swaminathan_file),
    " does not contain a data frame."
  )
}

if (!is.data.frame(stress_objective3)) {
  stop(
    basename(stress_objective3_file),
    " does not contain a data frame."
  )
}

required_swaminathan_columns <- c(
  "Author",
  "ID",
  "Traceability_ID",
  "Treatment",
  robust_variables,
  pc_variables,
  "Behavioural_Index",
  "Swaminathan_class"
)

missing_swaminathan_columns <- setdiff(
  required_swaminathan_columns,
  names(classification_swaminathan)
)

if (length(missing_swaminathan_columns) > 0L) {
  stop(
    "The corrected Swaminathan object is missing:\n",
    paste(missing_swaminathan_columns, collapse = ", ")
  )
}

required_stress_columns <- c(
  "Author",
  "ID",
  "Traceability_ID",
  robust_variables
)

missing_stress_columns <- setdiff(
  required_stress_columns,
  names(stress_objective3)
)

if (length(missing_stress_columns) > 0L) {
  stop(
    "The definitive Objective 3 Stress object is missing:\n",
    paste(missing_stress_columns, collapse = ", ")
  )
}

# ------------------------------------------------------------
# 5. Recover the definitive 89 Stress fish
# ------------------------------------------------------------

stress_pca <- classification_swaminathan %>%
  dplyr::filter(
    Treatment == "Stress"
  ) %>%
  dplyr::mutate(
    Author = trimws(as.character(Author)),
    ID = trimws(as.character(ID)),
    Traceability_ID = trimws(as.character(Traceability_ID))
  ) %>%
  dplyr::arrange(
    Traceability_ID
  )

stress_objective3 <- stress_objective3 %>%
  dplyr::mutate(
    Author = trimws(as.character(Author)),
    ID = trimws(as.character(ID)),
    Traceability_ID = trimws(as.character(Traceability_ID))
  ) %>%
  dplyr::arrange(
    Traceability_ID
  )

if (nrow(stress_pca) != expected_stress_n) {
  stop(
    "Expected exactly 89 Stress fish in the corrected Swaminathan object; found ",
    nrow(stress_pca),
    "."
  )
}

if (nrow(stress_objective3) != expected_stress_n) {
  stop(
    "The definitive Objective 3 Stress object does not contain 89 fish."
  )
}

if (
  anyNA(stress_pca$Author) ||
  anyNA(stress_pca$ID) ||
  anyNA(stress_pca$Traceability_ID) ||
  any(stress_pca$Author == "") ||
  any(stress_pca$ID == "") ||
  any(stress_pca$Traceability_ID == "")
) {
  stop(
    "Missing or empty Author + ID traceability values were detected."
  )
}

if (
  anyDuplicated(stress_pca[c("Author", "ID")]) > 0L ||
  anyDuplicated(stress_pca$Traceability_ID) > 0L
) {
  stop(
    "Duplicated Author + ID traceability keys were detected."
  )
}

if (
  !identical(
    stress_pca$Traceability_ID,
    stress_objective3$Traceability_ID
  )
) {
  stop(
    "The PCA + quantiles Stress fish do not match the definitive Objective 3 cohort."
  )
}

stress_provenance_difference <- vapply(
  robust_variables,
  function(variable_i) {
    max(
      abs(
        stress_pca[[variable_i]] -
          stress_objective3[[variable_i]]
      )
    )
  },
  numeric(1)
)

if (
  any(!is.finite(stress_provenance_difference)) ||
  any(stress_provenance_difference > numeric_tolerance)
) {
  stop(
    "The robust coordinates do not reproduce the definitive Objective 3 Stress data."
  )
}

if (
  any(
    !is.finite(
      as.matrix(
        stress_pca[
          c(
            robust_variables,
            pc_variables,
            "Behavioural_Index"
          )
        ]
      )
    )
  )
) {
  stop(
    "Missing or non-finite analytical values detected in the Stress population."
  )
}

# ------------------------------------------------------------
# 6. Calculate P25 and P75 within Stress only
# ------------------------------------------------------------

p25 <- unname(
  stats::quantile(
    stress_pca$Behavioural_Index,
    probs = 0.25,
    type = 7,
    na.rm = FALSE
  )
)

p75 <- unname(
  stats::quantile(
    stress_pca$Behavioural_Index,
    probs = 0.75,
    type = 7,
    na.rm = FALSE
  )
)

if (
  length(p25) != 1L ||
  length(p75) != 1L ||
  !is.finite(p25) ||
  !is.finite(p75) ||
  p25 >= p75
) {
  stop(
    "Invalid P25/P75 thresholds were obtained."
  )
}

# ------------------------------------------------------------
# 7. Classify the 89 Stress fish
# ------------------------------------------------------------

stress_pca <- stress_pca %>%
  dplyr::mutate(
    PCA_Quantile_Class = dplyr::case_when(
      Behavioural_Index <= p25 ~
        "Susceptible",

      Behavioural_Index >= p75 ~
        "Resilient",

      TRUE ~
        "Intermediate"
    ),
    PCA_Quantile_Class = factor(
      PCA_Quantile_Class,
      levels = required_classes
    )
  )

if (anyNA(stress_pca$PCA_Quantile_Class)) {
  stop(
    "Missing PCA + quantiles classifications were produced."
  )
}

classification_counts <- stress_pca %>%
  dplyr::count(
    PCA_Quantile_Class,
    name = "n",
    .drop = FALSE
  ) %>%
  dplyr::mutate(
    Percentage =
      100 *
      n /
      expected_stress_n
  )

if (
  sum(classification_counts$n) != expected_stress_n
) {
  stop(
    "PCA + quantiles classification counts do not sum to 89."
  )
}

# ------------------------------------------------------------
# 8. Descriptive statistics by PCA + quantiles class
# ------------------------------------------------------------

pca_quantile_summary <- stress_pca %>%
  dplyr::group_by(
    PCA_Quantile_Class
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),
    Percentage =
      100 *
      n /
      expected_stress_n,

    Mean_Index =
      mean(Behavioural_Index),

    SD_Index =
      stats::sd(Behavioural_Index),

    CV_Index_percent =
      dplyr::if_else(
        abs(Mean_Index) > .Machine$double.eps,
        100 * SD_Index / abs(Mean_Index),
        NA_real_
      ),

    Median_Index =
      stats::median(Behavioural_Index),

    IQR_Index =
      stats::IQR(Behavioural_Index),

    Mean_distance_rz =
      mean(distance_rz),

    Mean_crossing_rz =
      mean(crossing_rz),

    Mean_top_entry_rz =
      mean(top_entry_rz),

    Mean_top_time_rz =
      mean(top_time_rz),

    Median_distance_rz =
      stats::median(distance_rz),

    Median_crossing_rz =
      stats::median(crossing_rz),

    Median_top_entry_rz =
      stats::median(top_entry_rz),

    Median_top_time_rz =
      stats::median(top_time_rz),

    .groups = "drop"
  )

# ------------------------------------------------------------
# 9. Diagnostic classification figure
# ------------------------------------------------------------

p_pca_quantile <- ggplot2::ggplot(
  stress_pca,
  ggplot2::aes(
    x = Behavioural_Index,
    fill = PCA_Quantile_Class
  )
) +
  ggplot2::geom_histogram(
    bins = 20,
    colour = "black",
    alpha = 0.75
  ) +
  ggplot2::geom_vline(
    xintercept = c(
      p25,
      p75
    ),
    linetype = "dashed",
    linewidth = 0.9
  ) +
  ggplot2::labs(
    x = "Multivariate behavioural index",
    y = "Frequency",
    fill = NULL
  ) +
  ggplot2::theme_classic(
    base_size = 14,
    base_family = "Arial"
  ) +
  ggplot2::theme(
    legend.position = "top"
  )

print(
  p_pca_quantile
)

ggplot2::ggsave(
  filename = pdf_output,
  plot = p_pca_quantile,
  device = grDevices::cairo_pdf,
  width = 7.5,
  height = 5.5,
  units = "in",
  bg = "white"
)

ggplot2::ggsave(
  filename = tiff_output,
  plot = p_pca_quantile,
  width = 7.5,
  height = 5.5,
  units = "in",
  dpi = 600,
  compression = "lzw",
  bg = "white"
)

# ------------------------------------------------------------
# 10. Preliminary method-size table
# ------------------------------------------------------------

swaminathan_stress <- classification_swaminathan %>%
  dplyr::filter(
    Treatment == "Stress"
  )

method_size_table <- tibble::tibble(
  Method = c(
    "Swaminathan",
    "PCA + quantiles"
  ),

  Susceptible = c(
    sum(
      swaminathan_stress$Swaminathan_class ==
        "Susceptible",
      na.rm = TRUE
    ),
    sum(
      stress_pca$PCA_Quantile_Class ==
        "Susceptible"
    )
  ),

  Intermediate = c(
    NA_integer_,
    sum(
      stress_pca$PCA_Quantile_Class ==
        "Intermediate"
    )
  ),

  Resilient = c(
    sum(
      swaminathan_stress$Swaminathan_class ==
        "Resilient",
      na.rm = TRUE
    ),
    sum(
      stress_pca$PCA_Quantile_Class ==
        "Resilient"
    )
  )
)

# ------------------------------------------------------------
# 11. Export tables
# ------------------------------------------------------------

classification_export <- stress_pca %>%
  dplyr::select(
    Author,
    ID,
    Traceability_ID,
    Treatment,
    dplyr::all_of(
      robust_variables
    ),
    dplyr::all_of(
      pc_variables
    ),
    Behavioural_Index,
    PCA_Quantile_Class
  ) %>%
  dplyr::arrange(
    Author,
    ID
  )

threshold_export <- data.frame(
  Quantile = c(
    "P25",
    "P75"
  ),
  Value = c(
    p25,
    p75
  )
)

openxlsx::write.xlsx(
  list(
    Quantile_thresholds =
      threshold_export,

    Classification =
      classification_export,

    Class_summary =
      pca_quantile_summary,

    Preliminary_method_sizes =
      method_size_table
  ),
  file =
    xlsx_output,
  overwrite = TRUE
)

# ------------------------------------------------------------
# 12. Save corrected Objective 4 objects
# ------------------------------------------------------------

saveRDS(
  stress_pca,
  classification_output
)

saveRDS(
  pca_quantile_summary,
  summary_output
)

saveRDS(
  list(
    Analysis =
      "Objective 4 - PCA + quantiles",
    Analytical_population =
      "Stress only",
    Stress_n =
      expected_stress_n,
    Traceability =
      "Author + ID",
    Behavioural_Index_source =
      swaminathan_file,
    Stress_source_file =
      stress_objective3_file,
    Quantile_type =
      7L,
    P25 =
      p25,
    P75 =
      p75,
    Classification_rule =
      c(
        Susceptible =
          "Behavioural_Index <= P25",
        Intermediate =
          "P25 < Behavioural_Index < P75",
        Resilient =
          "Behavioural_Index >= P75"
      )
  ),
  thresholds_output
)

saveRDS(
  method_size_table,
  method_size_output
)

capture.output(
  utils::sessionInfo(),
  file =
    session_info_output
)

# ------------------------------------------------------------
# 13. Confirm output creation
# ------------------------------------------------------------

expected_output_files <- c(
  classification_output,
  summary_output,
  thresholds_output,
  method_size_output,
  xlsx_output,
  pdf_output,
  tiff_output,
  session_info_output
)

missing_output_files <- expected_output_files[
  !file.exists(
    expected_output_files
  )
]

if (length(missing_output_files) > 0L) {
  stop(
    "The following PCA + quantiles outputs were not created:\n",
    paste(
      missing_output_files,
      collapse = "\n"
    )
  )
}

# ------------------------------------------------------------
# 14. Final console audit
# ------------------------------------------------------------

cat("\n============================================================\n")
cat("OBJECTIVE 4 - PCA + QUANTILES CLASSIFICATION\n")
cat("============================================================\n")

cat(
  "\nSwaminathan object source:\n",
  swaminathan_file,
  "\n",
  sep = ""
)

cat(
  "\nDefinitive Objective 3 Stress source:\n",
  stress_objective3_file,
  "\n",
  sep = ""
)

cat(
  "\nStress fish:\n"
)

print(
  nrow(stress_pca)
)

cat(
  "\nDuplicate Author + ID combinations:\n"
)

print(
  sum(
    duplicated(
      stress_pca[
        c(
          "Author",
          "ID"
        )
      ]
    )
  )
)

cat(
  "\nMaximum absolute difference from definitive Objective 3 robust coordinates:\n"
)

print(
  stress_provenance_difference
)

cat(
  "\nP25 and P75 calculated within Stress only:\n"
)

print(
  threshold_export
)

cat(
  "\nPCA + quantiles classification:\n"
)

print(
  classification_counts,
  n = Inf,
  width = Inf
)

cat(
  "\nClass-level Behavioural_Index and robust-behaviour summary:\n"
)

print(
  pca_quantile_summary,
  n = Inf,
  width = Inf
)

cat(
  "\nPreliminary method-size table:\n"
)

print(
  method_size_table,
  n = Inf,
  width = Inf
)

cat(
  "\nNo behavioural variable was renormalised.\n"
)

cat(
  "No PCA was refitted and no new Behavioural_Index was constructed.\n"
)

cat(
  "The P25/P75 thresholds were calculated exclusively in the 89 Stress fish.\n"
)

cat(
  "\nOutputs saved successfully.\n"
)

cat("\n============================================================\n")
